    'meta.notfoundTitle': 'Seite nicht gefunden | Dictation Notes',
    'meta.notfoundDesc': 'Diese URL gehört nicht zur Dictation-Notes-Website.',
    'home.h1': 'Dictation Notes',
    'home.lead': 'Machen Sie aus Meetings, in denen Sie sitzen, Live-Text und dann einen Satz, den Sie sagen können. Diktat auf dem Gerät ist kostenlos. Cloud und KI nutzen Ihre eigenen Schlüssel. Die App ist im App Store.',
    'home.cta': 'Im App Store laden',
